/*
 * ====================================================================
 *  SOUND FOR THE ONE MOVIE CHALLENGE
 * ====================================================================
 *
 * Every sound here is generated by the browser, not loaded from a file.
 *
 * That is a deliberate choice. Audio files would mean shipping megabytes
 * for three short cues, sorting out a licence for each one, and hoping a
 * CDN stays up. The Web Audio API builds the same cues out of oscillators
 * and envelopes in a couple of hundred bytes of code, with nothing to
 * download and nothing to credit.
 *
 * What the three cues are:
 *   hum     a low two-note drone that slowly opens up, under the search
 *   blip    a short tone at each stage of the search, rising each time
 *   reveal  a major chord that blooms and decays, when the film arrives
 *   miss    a short descending pair, when the search fails
 *
 * Browsers refuse to start audio until the visitor has interacted with the
 * page, which is why nothing is created until the first call — and the
 * first call always comes from the click on Find My Movie.
 */

let context = null;

const getContext = () => {
  if (typeof window === "undefined") return null;

  const AudioContextClass = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextClass) return null;          // very old browser; stay silent

  if (!context) context = new AudioContextClass();
  // Safari in particular parks the context until a gesture resumes it
  if (context.state === "suspended") context.resume();

  return context;
};

/*
 * One tone with a shaped envelope.
 *
 * The ramps matter more than the notes. A gain that jumps straight to its
 * value clicks audibly, because the speaker is asked to move instantly, so
 * every sound here fades in over a few milliseconds and decays rather than
 * stopping dead.
 */
const tone = ({ ac, type = "sine", freq, start, duration, peak, glideTo }) => {
  const osc = ac.createOscillator();
  const gain = ac.createGain();

  osc.type = type;
  osc.frequency.setValueAtTime(freq, start);
  if (glideTo) osc.frequency.exponentialRampToValueAtTime(glideTo, start + duration);

  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(peak, start + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);

  osc.connect(gain).connect(ac.destination);
  osc.start(start);
  osc.stop(start + duration + 0.05);
};

/*
 * The searching drone.
 *
 * Two detuned saw waves an octave apart, run through a low-pass filter
 * that opens from 220Hz to 1.1kHz across the search. The rising filter is
 * what makes it feel like something is being looked for and closing in;
 * the pitch itself barely moves.
 *
 * Returns the function that stops it, so the caller does not have to know
 * anything about the nodes.
 */
export const startSearchHum = (seconds) => {
  const ac = getContext();
  if (!ac) return () => {};

  const now = ac.currentTime;

  const low = ac.createOscillator();
  const high = ac.createOscillator();
  const filter = ac.createBiquadFilter();
  const gain = ac.createGain();

  low.type = "sawtooth";
  high.type = "sawtooth";
  low.frequency.setValueAtTime(55, now);
  high.frequency.setValueAtTime(110.6, now);     // slightly off the octave, so it beats

  filter.type = "lowpass";
  filter.Q.value = 6;
  filter.frequency.setValueAtTime(220, now);
  filter.frequency.exponentialRampToValueAtTime(1100, now + seconds);

  gain.gain.setValueAtTime(0.0001, now);
  gain.gain.exponentialRampToValueAtTime(0.045, now + 0.6);

  low.connect(filter);
  high.connect(filter);
  filter.connect(gain).connect(ac.destination);

  low.start(now);
  high.start(now);

  let stopped = false;
  return () => {
    if (stopped) return;
    stopped = true;
    const end = ac.currentTime;
    gain.gain.cancelScheduledValues(end);
    gain.gain.setValueAtTime(Math.max(gain.gain.value, 0.0001), end);
    gain.gain.exponentialRampToValueAtTime(0.0001, end + 0.25);
    low.stop(end + 0.3);
    high.stop(end + 0.3);
  };
};

// A short tick as the search moves on; each stage is a step higher.
export const playStageBlip = (stageIndex) => {
  const ac = getContext();
  if (!ac) return;

  const now = ac.currentTime;
  const freq = [660, 880, 1320][stageIndex] || 660;

  tone({ ac, type: "triangle", freq, start: now, duration: 0.18, peak: 0.07 });
};

/*
 * The arrival.
 *
 * A major triad — root, third, fifth, plus the octave — with each note
 * entering 60ms after the last, so the chord opens rather than lands flat.
 * A low sine underneath gives it some weight.
 */
export const playReveal = () => {
  const ac = getContext();
  if (!ac) return;

  const now = ac.currentTime;
  const chord = [523.25, 659.25, 783.99, 1046.5];   // C5 E5 G5 C6

  chord.forEach((freq, i) => {
    tone({
      ac,
      type: "sine",
      freq,
      start: now + i * 0.06,
      duration: 1.5 - i * 0.12,
      peak: 0.06,
    });
  });

  tone({ ac, type: "sine", freq: 130.81, start: now, duration: 1.6, peak: 0.05 });
};

// Two falling notes, for a search that found nothing or broke.
export const playMiss = () => {
  const ac = getContext();
  if (!ac) return;

  const now = ac.currentTime;
  tone({ ac, type: "triangle", freq: 330, start: now, duration: 0.25, peak: 0.06 });
  tone({ ac, type: "triangle", freq: 220, start: now + 0.16, duration: 0.5, peak: 0.06 });
};
